<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width, initial-scale=1">
  <title>Sorting Visualizer</title>
  <style>
    :root {
      color-scheme: dark;
      --bg: #090d18;
      --panel: #121827;
      --text: #eef2ff;
      --muted: #94a3b8;
      --accent: #8b5cf6;
      --accent2: #22d3ee;
    }

    * { box-sizing: border-box; }

    body {
      min-height: 100vh;
      margin: 0;
      display: grid;
      place-items: center;
      padding: 24px;
      color: var(--text);
      background:
        radial-gradient(circle at 50% 0%, #1d2440 0, transparent 45%),
        var(--bg);
      font-family: system-ui, sans-serif;
    }

    main {
      width: min(920px, 100%);
      padding: 24px;
      border: 1px solid #273047;
      border-radius: 18px;
      background: color-mix(in srgb, var(--panel) 92%, transparent);
      box-shadow: 0 24px 70px #0008;
    }

    header {
      display: flex;
      align-items: center;
      justify-content: space-between;
      gap: 18px;
      margin-bottom: 20px;
    }

    h1 {
      margin: 0;
      font-size: clamp(1.35rem, 4vw, 2rem);
    }

    p {
      margin: 5px 0 0;
      color: var(--muted);
      font-size: .9rem;
    }

    .controls {
      display: flex;
      flex-wrap: wrap;
      justify-content: flex-end;
      gap: 9px;
    }

    button {
      border: 1px solid #34405c;
      border-radius: 9px;
      padding: 9px 15px;
      color: var(--text);
      background: #1a2235;
      font: inherit;
      font-weight: 650;
      cursor: pointer;
    }

    button:hover { background: #242e45; }
    button:disabled { opacity: .48; cursor: not-allowed; }

    #sort {
      border-color: #7657da;
      background: var(--accent);
    }

    #sort:hover { background: #9d78ff; }

    #bars {
      height: min(62vh, 500px);
      min-height: 280px;
      display: flex;
      align-items: flex-end;
      gap: clamp(2px, .55vw, 7px);
      padding: 20px 16px 0;
      overflow: hidden;
      border: 1px solid #273047;
      border-radius: 12px;
      background:
        linear-gradient(#ffffff08 1px, transparent 1px) 0 0 / 100% 25%,
        #080c16;
    }

    .bar {
      flex: 1 1 0;
      min-width: 2px;
      border-radius: 5px 5px 1px 1px;
      background: linear-gradient(to top, var(--accent), var(--accent2));
      box-shadow: 0 0 12px #22d3ee22;
      transition: height 100ms ease, filter 100ms ease;
    }

    .bar.active {
      filter: brightness(1.55) saturate(1.4);
      background: linear-gradient(to top, #f97316, #facc15);
    }

    @media (max-width: 650px) {
      header { align-items: flex-start; flex-direction: column; }
      .controls { justify-content: flex-start; }
      main { padding: 17px; }
    }
  </style>
</head>
<body>
  <main>
    <header>
      <div>
        <h1>Sorting Visualizer</h1>
        <p>Bubble sort, one comparison at a time</p>
      </div>
      <div class="controls">
        <button id="shuffle" type="button">Shuffle</button>
        <button id="reset" type="button">Reset</button>
        <button id="sort" type="button">Sort</button>
      </div>
    </header>
    <div id="bars" aria-label="Array values"></div>
  </main>

  <script>
    (() => {
      const bars = document.querySelector("#bars");
      const sortButton = document.querySelector("#sort");
      const shuffleButton = document.querySelector("#shuffle");
      const resetButton = document.querySelector("#reset");

      const initial = Array.from({ length: 36 }, (_, i) => i + 1);
      let values = initial.slice();
      let i = 0;
      let end = values.length - 1;
      let swapped = false;
      let active = [];
      let running = false;
      let timer = null;

      function resetState() {
        i = 0;
        end = values.length - 1;
        swapped = false;
        active = [];
      }

      function isSorted() {
        for (let n = 1; n < values.length; n++) {
          if (values[n - 1] > values[n]) return false;
        }
        return true;
      }

      function draw() {
        bars.replaceChildren();
        const max = Math.max(...values.map(Math.abs), 1);

        values.forEach((value, index) => {
          const bar = document.createElement("div");
          bar.className = "bar" + (active.includes(index) ? " active" : "");
          bar.style.height = `${Math.max(2, Math.abs(value) / max * 100)}%`;
          bar.title = String(value);
          bar.setAttribute("aria-label", String(value));
          bars.appendChild(bar);
        });
      }

      function sortStep() {
        if (values.length < 2 || end <= 0 || isSorted()) {
          active = [];
          draw();
          return true;
        }

        active = [i, i + 1];

        if (values[i] > values[i + 1]) {
          [values[i], values[i + 1]] = [values[i + 1], values[i]];
          swapped = true;
        }

        i++;

        if (i >= end) {
          if (!swapped) {
            end = 0;
          } else {
            end--;
            i = 0;
            swapped = false;
          }
        }

        const done = end <= 0 || isSorted();
        if (done) active = [];
        draw();
        return done;
      }

      function stop() {
        running = false;
        clearTimeout(timer);
        timer = null;
        sortButton.disabled = false;
        shuffleButton.disabled = false;
        resetButton.disabled = false;
      }

      function animate() {
        if (!running) return;
        if (sortStep()) {
          stop();
          return;
        }
        timer = setTimeout(animate, 35);
      }

      sortButton.addEventListener("click", () => {
        if (running) return;
        running = true;
        sortButton.disabled = true;
        shuffleButton.disabled = true;
        resetButton.disabled = true;
        animate();
      });

      shuffleButton.addEventListener("click", () => {
        stop();
        for (let n = values.length - 1; n > 0; n--) {
          const j = Math.floor(Math.random() * (n + 1));
          [values[n], values[j]] = [values[j], values[n]];
        }
        resetState();
        draw();
      });

      resetButton.addEventListener("click", () => {
        stop();
        values = initial.slice();
        resetState();
        draw();
      });

      window.viz = {
        array() {
          return values.slice();
        },
        setArray(a) {
          stop();
          if (!Array.isArray(a) || !a.every(Number.isFinite)) {
            throw new TypeError("setArray expects an array of finite numbers");
          }
          values = a.slice();
          resetState();
          draw();
        },
        sortStep,
        sorted: isSorted
      };

      draw();
    })();
  </script>
</body>
</html>
